    private function collectBraceBalance(Tokens $tokens): array
    {
        $round = 0;
        $curly = 0;
        $square = 0;
        $minRound = 0;
        $minCurly = 0;
        $minSquare = 0;
        foreach ($tokens as $token) {
            $content = $token->getContent();
            if ('(' === $content) {
                ++$round;
            } elseif (')' === $content) {
                --$round;
                $minRound = min($minRound, $round);
            } elseif ('{' === $content) {
                ++$curly;
            } elseif ('}' === $content) {
                --$curly;
                $minCurly = min($minCurly, $curly);
            } elseif ('[' === $content) {
                ++$square;
            } elseif (']' === $content) {
                --$square;
                $minSquare = min($minSquare, $square);
            }
        }

        return [
            'round' => $round,
            'curly' => $curly,
            'square' => $square,
            'underflow' => $minRound < 0 || $minCurly < 0 || $minSquare < 0,
        ];
    }

    private function collectOperatorDensity(Tokens $tokens): array
    {
        $assign = 0;
        $compare = 0;
        $logic = 0;
        $concat = 0;
        foreach ($tokens as $token) {
            if ($token->equalsAny(['=', [T_PLUS_EQUAL], [T_MINUS_EQUAL], [T_MUL_EQUAL], [T_DIV_EQUAL], [T_CONCAT_EQUAL]])) {
                ++$assign;
            } elseif ($token->equalsAny(['==', '===', '!=', '<>', '!==', '<', '>', '<=', '>=', [T_IS_EQUAL], [T_IS_IDENTICAL], [T_IS_NOT_EQUAL], [T_IS_NOT_IDENTICAL], [T_IS_SMALLER_OR_EQUAL], [T_IS_GREATER_OR_EQUAL]])) {
                ++$compare;
            } elseif ($token->equalsAny(['&&', '||', [T_BOOLEAN_AND], [T_BOOLEAN_OR], [T_LOGICAL_AND], [T_LOGICAL_OR], [T_LOGICAL_XOR]])) {
                ++$logic;
            } elseif ($token->equals('.')) {
                ++$concat;
            }
        }

        return ['assign' => $assign, 'compare' => $compare, 'logic' => $logic, 'concat' => $concat];
    }

