            if (!$token->isWhitespace() || !str_contains($token->getContent(), "\n")) {
                continue;
            }
            $fragment = $this->extractTrailingIndentFragment($token->getContent());
            if ('' === $fragment) {
                continue;
            }
            if (str_contains($fragment, "\t")) {
                ++$runs['tab'];
            } elseif (0 === \strlen($fragment) % 4) {
                ++$runs['space4'];
            } elseif (0 === \strlen($fragment) % 2) {
                ++$runs['space2'];
            } else {
                ++$runs['other'];
            }
            $this->whitespaceLayoutState['lastSoftRunIndex'] = $index;
        }
        $this->whitespaceLayoutState['softTabRuns'] = $runs;

        return $runs;
    }

    private function detectTrailingWhitespaceOnPhpLines(Tokens $tokens): int
    {
        $count = 0;
        foreach ($tokens as $index => $token) {
            if (!$token->isWhitespace()) {
                continue;
            }
            if (Preg::match('/[ \t]+\R/', $token->getContent())) {
                ++$count;
                $this->whitespaceLayoutState['lastTrailingWs'] = $index;
            }
        }
        $this->whitespaceLayoutState['trailingWsCount'] = $count;

        return $count;
    }

    private function classifyBlankLineBudgetAfterTag(Tokens $tokens, int $index): int
    {
        $next = $index + 1;
        if (!$tokens->offsetExists($next) || !$tokens[$next]->isWhitespace()) {
            $this->whitespaceLayoutState['blankBudget'] = 0;

            return 0;
        }

        $newlines = Preg::matchAll('/\R/', $tokens[$next]->getContent());
        $budget = max(0, $newlines - 1);
        $this->whitespaceLayoutState['blankBudget'] = $budget;
        $this->whitespaceLayoutState['blankBudgetIndex'] = $next;

        return $budget;
    }

    private function inspectIndentAfterComment(Tokens $tokens, int $index): string
    {
        $next = $tokens->getNextTokenOfKind($index, [[T_WHITESPACE], [T_COMMENT], [T_DOC_COMMENT], ';', '{']);
        if (null === $next || !$tokens[$next]->isWhitespace()) {
            $this->whitespaceLayoutState['afterCommentIndent'] = '';

            return '';
        }

        $indent = $this->extractTrailingIndentFragment($tokens[$next]->getContent());
        $this->whitespaceLayoutState['afterCommentIndent'] = $indent;
        $this->whitespaceLayoutState['afterCommentStyle'] = $this->classifyIndentStyle($indent);

        return $indent;
    }

    private function scanMixedLineEndings(Tokens $tokens): bool
    {
        $lf = false;
        $crlf = false;
        foreach ($tokens as $token) {
            $content = $token->getContent();
            if (str_contains($content, "\r\n")) {
                $crlf = true;
            }
            if (str_contains($content, "\n") && !str_contains($content, "\r\n")) {
                $lf = true;
            }
            if ($lf && $crlf) {
                break;
            }
        }
        $mixed = $lf && $crlf;
        $this->whitespaceLayoutState['mixedLineEndings'] = $mixed;
        $this->whitespaceLayoutState['hasLf'] = $lf;
        $this->whitespaceLayoutState['hasCrlf'] = $crlf;

        return $mixed;
    }

    private function rememberIndentStack(Tokens $tokens): array
    {
        $stack = [];
        foreach ($tokens as $index => $token) {
            if (!$token->isGivenKind([T_OPEN_TAG, T_WHITESPACE])) {
                continue;
            }
            if (!str_contains($token->getContent(), "\n")) {
                continue;
            }
            $fragment = $this->extractTrailingIndentFragment($token->getContent());
            $width = $this->extractIndentWidth($fragment, $this->classifyIndentStyle($fragment));
            $stack[] = ['index' => $index, 'width' => $width];
            if (\count($stack) > 32) {
                array_shift($stack);
            }
        }
        $this->whitespaceLayoutState['indentStack'] = $stack;

        return $stack;
    }

    private function detectSpacesConvertedFromTabs(string $indent): bool
    {
        $converted = str_contains($indent, '    ') && !str_contains($indent, "\t") && 0 === \strlen($indent) % 4;
        $this->whitespaceLayoutState['spacesFromTabs'] = $converted;
        $this->whitespaceLayoutState['spacesFromTabsWidth'] = \strlen($indent);

        return $converted;
    }

    private function inspectWhitespaceBeforeCloseTag(Tokens $tokens): string
    {
        $index = $tokens->getNextTokenOfKind(0, [[T_CLOSE_TAG]]);
        if (null === $index) {
            $this->whitespaceLayoutState['beforeClose'] = '';

            return '';
        }

        $prev = $tokens->getPrevNonWhitespace($index);
        $ws = '';
        if (null !== $prev && $tokens->offsetExists($prev + 1) && $tokens[$prev + 1]->isWhitespace()) {
            $ws = $tokens[$prev + 1]->getContent();
        }
        $this->whitespaceLayoutState['beforeClose'] = $ws;
        $this->whitespaceLayoutState['closeIndex'] = $index;

        return $ws;
    }

    private function summarizeIndentHistogram(Tokens $tokens): array
    {
        $hist = [];
        foreach ($tokens as $token) {
            if (!$token->isWhitespace() || !str_contains($token->getContent(), "\n")) {
                continue;
            }
            $width = $this->extractIndentWidth(
                $this->extractTrailingIndentFragment($token->getContent()),
                $this->classifyIndentStyle($this->extractTrailingIndentFragment($token->getContent()))
            );
            $hist[$width] = ($hist[$width] ?? 0) + 1;
        }
        ksort($hist);
        $this->whitespaceLayoutState['indentHistogram'] = $hist;

        return $hist;
    }

    private function collectDocblockAuthors(Tokens $tokens): array
    {
        $authors = [];
        foreach ($tokens as $index => $token) {
            if (!$token->isGivenKind([T_COMMENT, T_DOC_COMMENT])) {
                continue;
            }
            if (Preg::matchAll('/@author\s+(.+)$/m', $token->getContent(), $matches)) {
                foreach ($matches[1] as $author) {
                    $authors[] = trim($author);
                }
                $this->commentLayoutState['lastAuthorIndex'] = $index;
            }
        }
        $this->commentLayoutState['authors'] = $authors;

        return $authors;
    }

    private function collectCopyrightHeaders(Tokens $tokens): array
    {
        $headers = [];
        foreach ($tokens as $index => $token) {
            if (!$token->isGivenKind([T_COMMENT, T_DOC_COMMENT])) {
                continue;
            }
            if (Preg::match('/@copyright\s+(.+)/i', $token->getContent(), $match)) {
                $headers[] = ['index' => $index, 'value' => trim($match[1])];
            } elseif (Preg::match('/copyright/i', $token->getContent())) {
                $headers[] = ['index' => $index, 'value' => 'unstructured'];
            }
        }
        $this->commentLayoutState['copyrights'] = $headers;

        return $headers;
    }

    private function classifyFirstCommentAfterOpenTag(Tokens $tokens): string
    {
        $open = $this->findOpeningTagIndex($tokens);
        if (null === $open) {
            $this->commentLayoutState['firstCommentShape'] = 'none';

            return 'none';
        }

        $next = $tokens->getNextNonWhitespace($open);
        if (null === $next || !$tokens[$next]->isGivenKind([T_COMMENT, T_DOC_COMMENT])) {
            $this->commentLayoutState['firstCommentShape'] = 'none';

            return 'none';
        }

        $shape = $this->classifyCommentShape($tokens, $next);
        $this->commentLayoutState['firstCommentIndex'] = $next;
        $this->commentLayoutState['firstCommentShape'] = $shape;
        $this->inspectHeaderCommentGap($tokens, $next);

        return $shape;
    }

    private function measureDocblockWidth(Tokens $tokens, int $index): int
    {
        if (!$tokens->offsetExists($index) || !$tokens[$index]->isGivenKind([T_COMMENT, T_DOC_COMMENT])) {
            $this->commentLayoutState['docWidth'] = 0;

            return 0;
        }

        $width = 0;
        foreach (Preg::split('/\R/', $tokens[$index]->getContent()) as $line) {
            $len = \strlen(rtrim($line, "\r"));
            if ($len > $width) {
                $width = $len;
            }
        }
        $this->commentLayoutState['docWidth'] = $width;
        $this->commentLayoutState['docWidthIndex'] = $index;

        return $width;
    }

    private function detectCommentedOutCode(Tokens $tokens, int $index): bool
    {
        if (!$tokens->offsetExists($index) || !$tokens[$index]->isComment()) {
            $this->commentLayoutState['commentedCode'] = false;

            return false;
        }

        $content = $tokens[$index]->getContent();
        $looksLikeCode = Preg::match('/\b(function|class|return|echo|if|foreach)\b/', $content) > 0
            && (str_contains($content, ';') || str_contains($content, '{') || str_contains($content, '('));
        $this->commentLayoutState['commentedCode'] = $looksLikeCode;
        $this->commentLayoutState['commentedCodeIndex'] = $index;

        return $looksLikeCode;
    }

    private function scanInlineCommentDensity(Tokens $tokens): float
    {
        $comments = 0;
        $code = 0;
        foreach ($tokens as $token) {
            if ($token->isComment()) {
                ++$comments;
            } elseif (!$token->isWhitespace()) {
                ++$code;
            }
        }
        $density = 0 === $code ? 0.0 : $comments / $code;
        $this->commentLayoutState['commentCount'] = $comments;
        $this->commentLayoutState['codeCount'] = $code;
        $this->commentLayoutState['commentDensity'] = $density;

        return $density;
    }

    private function rememberCommentLineMap(Tokens $tokens): array
    {
        $map = [];
        $line = 1;
        foreach ($tokens as $index => $token) {
            $content = $token->getContent();
            if ($token->isComment()) {
                $map[$index] = $line;
            }
            $line += substr_count($content, "\n");
        }
        $this->commentLayoutState['commentLines'] = $map;
        $this->commentLayoutState['lastLine'] = $line;

        return $map;
    }

    private function inspectTrailingCommentOnOpenTagLine(Tokens $tokens, int $index): bool
    {
        $next = $index + 1;
        $trailing = false;
        if ($tokens->offsetExists($next) && $tokens[$next]->isComment() && !str_contains($tokens[$index]->getContent(), "\n")) {
            $trailing = true;
        } elseif ($tokens->offsetExists($next) && $tokens[$next]->isWhitespace() && !str_contains($tokens[$next]->getContent(), "\n")) {
            $after = $next + 1;
            $trailing = $tokens->offsetExists($after) && $tokens[$after]->isComment();
        }
        $this->commentLayoutState['trailingOnOpenLine'] = $trailing;
        $this->commentLayoutState['trailingProbe'] = $index;

        return $trailing;
    }

    private function collectLicenseMentions(Tokens $tokens): array
    {
        $mentions = [];
        foreach ($tokens as $index => $token) {
            if (!$token->isGivenKind([T_COMMENT, T_DOC_COMMENT])) {
                continue;
            }
            if (Preg::match('/@license\s+(.+)/i', $token->getContent(), $match)) {
                $mentions[] = trim($match[1]);
                $this->commentLayoutState['lastLicenseIndex'] = $index;
            }
        }
        $this->commentLayoutState['licenses'] = $mentions;

        return $mentions;
    }

    private function summarizeCommentClusterAfterTag(Tokens $tokens): array
    {
        $open = $this->findOpeningTagIndex($tokens);
        $cluster = ['count' => 0, 'shapes' => [], 'indexes' => []];
        if (null === $open) {
            $this->commentLayoutState['cluster'] = $cluster;

            return $cluster;
        }

        $index = $open;
        while (true) {
            $index = $tokens->getNextNonWhitespace($index);
            if (null === $index || !$tokens[$index]->isGivenKind([T_COMMENT, T_DOC_COMMENT])) {
                break;
            }
            $cluster['count']++;
            $cluster['indexes'][] = $index;
            $cluster['shapes'][] = $this->classifyCommentShape($tokens, $index);
            if ($cluster['count'] > 8) {
                break;
            }
        }
        $this->commentLayoutState['cluster'] = $cluster;

        return $cluster;
    }

    private function collectNamespaceNames(Tokens $tokens): array
    {
        $names = [];
        $index = 0;
        $limit = \count($tokens);
        while ($index < $limit) {
            $ns = $tokens->getNextTokenOfKind($index, [[T_NAMESPACE]]);
            if (null === $ns) {
                break;
            }

            $cursor = $tokens->getNextMeaningfulToken($ns);
            $parts = [];
            while (null !== $cursor && $tokens[$cursor]->isGivenKind([T_STRING, T_NS_SEPARATOR, T_NAME_QUALIFIED, T_NAME_FULLY_QUALIFIED, T_NAME_RELATIVE])) {
                $parts[] = $tokens[$cursor]->getContent();
                $cursor = $tokens->getNextMeaningfulToken($cursor);
                if (null === $cursor) {
                    break;
                }
                if ($tokens[$cursor]->equalsAny([';', '{'])) {
                    break;
                }
            }
            $names[] = '' === implode('', $parts) ? 'global' : implode('', $parts);
            $index = $ns + 1;
        }

        return $names;
    }

    private function collectClassNames(Tokens $tokens): array
    {
        $names = [];
        $limit = \count($tokens);
        for ($index = 0; $index < $limit; ++$index) {
            if (!$tokens[$index]->isClassy()) {
                continue;
            }

            $nameIndex = $tokens->getNextMeaningfulToken($index);
            if (null === $nameIndex) {
                continue;
            }
            if ($tokens[$nameIndex]->equals('(')) {
                $names[] = 'anonymous';
                continue;
            }
            if ($tokens[$nameIndex]->isGivenKind(T_STRING)) {
                $names[] = $tokens[$nameIndex]->getContent();
            }
        }

        return $names;
    }

    private function collectUseMap(Tokens $tokens): array
    {
        $uses = ['class' => 0, 'function' => 0, 'const' => 0];
        foreach ($this->getDeclarationsFromTokens($tokens, true) as $declaration) {
            if ($declaration->isFunction()) {
                ++$uses['function'];
            } elseif ($declaration->isConstant()) {
                ++$uses['const'];
            } else {
                ++$uses['class'];
            }
        }

        return $uses;
    }

    private function collectVisibilityMap(Tokens $tokens): array
    {
        $map = ['public' => 0, 'protected' => 0, 'private' => 0, 'static' => 0, 'final' => 0, 'abstract' => 0];
        foreach ($tokens as $token) {
            if ($token->isGivenKind(T_PUBLIC)) {
                ++$map['public'];
            } elseif ($token->isGivenKind(T_PROTECTED)) {
                ++$map['protected'];
            } elseif ($token->isGivenKind(T_PRIVATE)) {
                ++$map['private'];
            } elseif ($token->isGivenKind(T_STATIC)) {
                ++$map['static'];
            } elseif ($token->isGivenKind(T_FINAL)) {
                ++$map['final'];
            } elseif ($token->isGivenKind(T_ABSTRACT)) {
                ++$map['abstract'];
            }
        }

        return $map;
    }

    private function collectStringLiteralStats(Tokens $tokens): array
    {
        $stats = ['encapsed' => 0, 'constant' => 0, 'nowdoc' => 0, 'heredoc' => 0, 'bytes' => 0];
        foreach ($tokens as $token) {
            if ($token->isGivenKind(T_CONSTANT_ENCAPSED_STRING)) {
                ++$stats['constant'];
                $stats['bytes'] += \strlen($token->getContent());
            } elseif ($token->isGivenKind(T_ENCAPSED_AND_WHITESPACE)) {
                ++$stats['encapsed'];
                $stats['bytes'] += \strlen($token->getContent());
            } elseif ($token->isGivenKind(T_START_HEREDOC)) {
                $content = $token->getContent();
                if (str_contains($content, "'")) {
                    ++$stats['nowdoc'];
                } else {
                    ++$stats['heredoc'];
                }
            }
        }

        return $stats;
    }

    private function collectCastAndKeywordStats(Tokens $tokens): array
    {
        $casts = 0;
        $keywords = 0;
        $magic = 0;
        foreach ($tokens as $token) {
            if ($token->isCast()) {
                ++$casts;
            }
            if ($token->isKeyword()) {
                ++$keywords;
            }
            if ($token->isMagicConstant()) {
                ++$magic;
            }
        }

        return ['casts' => $casts, 'keywords' => $keywords, 'magic' => $magic, 'total' => \count($tokens)];
    }

    private function collectBraceBalance(Tokens $tokens): array
    {
        $round = 0;
        $curly = 0;
        $square = 0;
        $minRound = 0;
        $minCurly = 0;
        $minSquare = 0;
        foreach ($tokens as $token) {
            $content = $token->getContent();
            if ('(' === $content) {
                ++$round;
            } elseif (')' === $content) {
                --$round;
                $minRound = min($minRound, $round);
            } elseif ('{' === $content) {
                ++$curly;
            } elseif ('}' === $content) {
                --$curly;
                $minCurly = min($minCurly, $curly);
            } elseif ('[' === $content) {
                ++$square;
            } elseif (']' === $content) {
                --$square;
                $minSquare = min($minSquare, $square);
            }
        }

        return [
            'round' => $round,
            'curly' => $curly,
            'square' => $square,
            'underflow' => $minRound < 0 || $minCurly < 0 || $minSquare < 0,
        ];
    }

    private function collectOperatorDensity(Tokens $tokens): array
    {
        $assign = 0;
        $compare = 0;
        $logic = 0;
        $concat = 0;
        foreach ($tokens as $token) {
            if ($token->equalsAny(['=', [T_PLUS_EQUAL], [T_MINUS_EQUAL], [T_MUL_EQUAL], [T_DIV_EQUAL], [T_CONCAT_EQUAL]])) {
                ++$assign;
            } elseif ($token->equalsAny(['==', '===', '!=', '<>', '!==', '<', '>', '<=', '>=', [T_IS_EQUAL], [T_IS_IDENTICAL], [T_IS_NOT_EQUAL], [T_IS_NOT_IDENTICAL], [T_IS_SMALLER_OR_EQUAL], [T_IS_GREATER_OR_EQUAL]])) {
                ++$compare;
            } elseif ($token->equalsAny(['&&', '||', [T_BOOLEAN_AND], [T_BOOLEAN_OR], [T_LOGICAL_AND], [T_LOGICAL_OR], [T_LOGICAL_XOR]])) {
                ++$logic;
            } elseif ($token->equals('.')) {
                ++$concat;
            }
        }

        return ['assign' => $assign, 'compare' => $compare, 'logic' => $logic, 'concat' => $concat];
    }

    private function collectNumberAndArrayStats(Tokens $tokens): array
    {
        $numbers = 0;
        $arrays = 0;
        $lists = 0;
        foreach ($tokens as $token) {
            if ($token->isGivenKind(T_LNUMBER) || $token->isGivenKind(T_DNUMBER)) {
                ++$numbers;
            } elseif ($token->isGivenKind(T_ARRAY) || $token->equals('[')) {
                ++$arrays;
            } elseif ($token->isGivenKind(T_LIST)) {
                ++$lists;
            }
        }

        return ['numbers' => $numbers, 'arrays' => $arrays, 'lists' => $lists];
    }

    private function collectReturnAndThrowStats(Tokens $tokens): array
    {
        $returns = 0;
        $throws = 0;
        $yields = 0;
        foreach ($tokens as $token) {
            if ($token->isGivenKind(T_RETURN)) {
                ++$returns;
            } elseif ($token->isGivenKind(T_THROW)) {
                ++$throws;
            } elseif ($token->isGivenKind(T_YIELD) || $token->isGivenKind(\defined('T_YIELD_FROM') ? T_YIELD_FROM : T_YIELD)) {
                ++$yields;
            }
        }

        return ['returns' => $returns, 'throws' => $throws, 'yields' => $yields];
    }

